o Biraxas. A reported nearby rift is at Shen’dralas 42.5,59.7."}, {title = "Pick up: Forlorn Gardens", note = "Take Forlorn Gardens93341, inspect the garden shrine and return to Mithera to turn it in. THEN accept What They've Done to My Peonies93362, kill4RowdyRoses,4TerribleTulips,20Marigolds and return. Take Word of the Woods93594 when offered and deliver to Woodwyrd.", goals = {{t = "accept", quest = 93341, title = "Forlorn Gardens", minLevel = 35, qlvl = 43, x = 53.2, y = 75.8, map = 2652}}}, {title = "Forlorn Gardens", goals = {{t = "complete", quest = 93341, title = "Forlorn Gardens"}, {t = "turnin", quest = 93341, title = "Forlorn Gardens", rewards = {xp = 1800}, x = 53.2, y = 75.8, map = 2652}}, note = "Take Forlorn Gardens93341, inspect the garden shrine and return to Mithera to turn it in. THEN accept What They've Done to My Peonies93362, kill4RowdyRoses,4TerribleTulips,20Marigolds and return. Take Word of the Woods93594 when offered and deliver to Woodwyrd. | Investigate the blue brazier in the small stone building in Forlorn Gardens at Shen’dralas about 70,80; return to Mithera."}, {title = "What They've Done to My Peonies", goals = {{t = "accept", quest = 93362, title = "What They've Done to My Peonies", minLevel = 35, qlvl = 43, x = 53.2, y = 75.8, map = 2652}, {t = "complete", quest = 93362, title = "What They've Done to My Peonies"}, {t = "turnin", quest = 93362, title = "What They've Done to My Peonies", rewards = {xp = 3600}, x = 53.2, y = 75.8, map = 2652}}, note = "Kill four Rowdy Roses, four Terrible Tulips and twenty Malevolent Marigolds in Forlorn Gardens."}, {title = "Word of the Woods", goals = {{t = "accept", quest = 93594, title = "Word of the Woods", minLevel = 35, qlvl = 43, x = 53.2, y = 75.8, map = 2652}, {t = "turnin", quest = 93594, title = "Word of the Woods", rewards = {xp = 360}, x = 69.4, y = 71.8, map = 2652}}, note = "Speak to Woodwyrd at Shen’dralas 69.4,71.8 and accept Rot and Regret. | If already completed, skip the quest an