46, title = "The Scepter of Celebras", rewards = {xp = 11100}}}, note = "Enter orange. Complete the Vylestem/scion objective, kill Noxxion for the Celebrian Rod, and handle the orange-wing khan. | Detour through purple for Lord Vyletongue's Celebrian Diamond and the purple-wing khan. Combine all five gems for The Pariah's Instructions. | Obtain Amulet of Spirits from The Nameless Prophet; use it to manifest the five Khan spirits and obtain each gem, then combine the gems into Amulet of Union."}, {title = "The Pariah's Instructions", goals = {{t = "accept", quest = 7067, title = "The Pariah's Instructions", minLevel = 39, qlvl = 48, x = 50.4, y = 86.6, map = 1443}, {t = "complete", quest = 7067, title = "The Pariah's Instructions"}, {t = "turnin", quest = 7067, title = "The Pariah's Instructions", rewards = {xp = 10650}, x = 50.4, y = 86.6, map = 1443}}, note = "Kill Celebras the Cursed. Turn in Legends, accept The Scepter of Celebras7046, and finish the ritual before leaving the junction. | Accept from Celebras the Redeemed after Legends, assist the ritual, and receive the scepter before moving into inner Maraudon."}, {title = "Vyletongue Corruption", goals = {{t = "accept", quest = 7029, title = "Vyletongue Corruption", minLevel = 41, qlvl = 47, x = 23.2, y = 70.2, map = 1443}, {t = "complete", quest = 7029, title = "Vyletongue Corruption"}, {t = "turnin", quest = 7029, title = "Vyletongue Corruption", rewards = {xp = 10250}, x = 23.2, y = 70.2, map = 1443}}, note = "Kill Rotgrip and collect Earth Song Water from the splash beneath the eastern stone bridge. Check every player's crystal, water, amulet and Seed of Life before leaving. | Hand in Pariah, Vyletongue and Corruption to their Desolace givers. Return to Shen'dralas, use the water on the burning tree beside Woodwyrd, and turn in Rot and Regret. | In Rotgrip’s pool below Princess, interact with Earth Song Splash, a geyser under the eastern stone bridge. Return to Woodwyrd and use the vial on the large burning tree next to him, then turn in."}, {title = "Corruption of Earth and Seed", goals = {{t = "accept", quest = 7064, title = "Corruption of Earth and Seed", minLevel = 45, qlvl = 51, x = 26.8, y = 77.6, map = 1443}, {t = "complete", quest = 7064, title = "Corruption of Earth and Seed"}, {t = "turnin", quest = 7064, title = "Corruption of Earth and Seed", rewards = {xp = 11900}, x = 26.8, y = 77.6, map = 1443}}, note = "Carry An'she's Radiance for the scheduled Mulgore return and Seed of Life for Moonglade. Neither delayed reward is counted in this chapter. | Each player fills the provided vial at the orange crystal pool before entering. Use the filled vial at eight Vylestem Vines and kill the spawned Noxxious Scions."}, {title = "Rot and Regret", goals = {{t = "accept", quest = 93404, title = "Rot and Regret", minLevel = 35, qlvl = 49, x = 69.4, y = 71.8, map = 2652}, {t = "complete", quest = 93404, title = "Rot and Regret"}, {t = "turnin", quest = 93404, title = "Rot and Regret", rewards = {xp = 11100}, x = 69.4, y = 71.8, map = 2652}}, note = "Kill Princess Theradras and return to Selendra outside Shadowprey Village. | 150 kills is a planning allowance for the entire run and exterior approach, not a measured clear count; do not add the same boss kills again. | Loot carvings and fragments if already doing their objectives, but no reset or extra farming is needed to make the XP model work."}}})
