r", goals = {{t = "complete", quest = 4284, title = "Crystals of Power"}, {t = "turnin", quest = 4284, title = "Crystals of Power", rewards = {xp = 5250}}}, note = "Larion and Muigin Hunt 5 Bloodpetal Lashers , 5 Bloodpetal Threshers , 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge. Bloodpetal Lasher slain ( 5 ) Bloodpetal Trapper slain ( 5 ) Bloodpetal Flayer slain ( 5 ) Bloodpetal Thresher slain ( 5 ) "}, {title = "The Northern Pylon", goals = {{t = "accept", quest = 4285, title = "The Northern Pylon", minLevel = 47, qlvl = 53}, {t = "complete", quest = 4285, title = "The Northern Pylon"}, {t = "turnin", quest = 4285, title = "The Northern Pylon", rewards = {xp = 3950}}}, note = "Beware of Pterrordax Kill 10 Pterrordax and 15 Frenzied Pterrordax , then speak to Spraggle Frock at Marshal's Refuge. Pterrordax slain ( 10 ) Frenzied Pterrordax slain ( 15 ) "}, {title = "The Eastern Pylon", goals = {{t = "accept", quest = 4287, title = "The Eastern Pylon", minLevel = 47, qlvl = 53}, {t = "complete", quest = 4287, title = "The Eastern Pylon"}, {t = "turnin", quest = 4287, title = "The Eastern Pylon", rewards = {xp = 3950}}}, note = "Gather the crystals and return Crystals of Power4284 to J.D.Collie BEFORE accepting the three pylon follow-ups. Then combine their visits with fixed crates/research equipment and Bloodpetal/pterrordax kills. Return all three pylon quests, then finish Making Sense of It4321. | Making Sense of It Speak with J.D. Collie in a moment. "}, {title = "Pick up: Finding the Source", note = "At the hot springs do Uncanny Crystal87492, available at50. On Fire Plume do Finding the Source974, available at51, and find Ringo for Lost!4492. The escort follow-up remains optional.", goals = {{t = "accept", quest = 974, title = "Finding the Source", minLevel = 51, qlvl = 55}}}, {title = "The Western Pylon", goals = {{t = "accept", quest = 4288, title = "The Western Pylon", minLevel = 47, qlvl = 53}, {t = "complete", quest = 4288, 